CREATE TABLE public.reseller_ai_settings (user_id uuid PRIMARY KEY DEFAULT auth.uid(), ideal_customer text NOT NULL DEFAULT '', paused_reason text NOT NULL DEFAULT '', pause_status integer, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.reseller_ai_settings TO authenticated; GRANT UPDATE(ideal_customer,updated_at) ON public.reseller_ai_settings TO authenticated; GRANT ALL ON public.reseller_ai_settings TO service_role;
ALTER TABLE public.reseller_ai_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY reseller_settings_read ON public.reseller_ai_settings FOR SELECT TO authenticated USING(user_id=auth.uid() AND (public.has_role(auth.uid(),'revendedor') OR public.has_role(auth.uid(),'super_admin')));
CREATE POLICY reseller_settings_insert ON public.reseller_ai_settings FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND paused_reason='' AND pause_status IS NULL AND (public.has_role(auth.uid(),'revendedor') OR public.has_role(auth.uid(),'super_admin')));
CREATE POLICY reseller_settings_update ON public.reseller_ai_settings FOR UPDATE TO authenticated USING(user_id=auth.uid() AND (public.has_role(auth.uid(),'revendedor') OR public.has_role(auth.uid(),'super_admin'))) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.reseller_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reseller_id uuid NOT NULL, salon_name text NOT NULL, contact_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', context text NOT NULL, ideal_customer_snapshot text NOT NULL DEFAULT '', score integer CHECK(score BETWEEN 0 AND 100), summary text NOT NULL DEFAULT '', call_recommended boolean NOT NULL DEFAULT false, call_reason text NOT NULL DEFAULT '', qualification_status text NOT NULL DEFAULT 'pending' CHECK(qualification_status IN ('pending','processing','qualified','failed')), qualification_error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), qualified_at timestamptz);
GRANT SELECT ON public.reseller_leads TO authenticated; GRANT ALL ON public.reseller_leads TO service_role;
ALTER TABLE public.reseller_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY reseller_leads_read ON public.reseller_leads FOR SELECT TO authenticated USING(reseller_id=auth.uid() AND (public.has_role(auth.uid(),'revendedor') OR public.has_role(auth.uid(),'super_admin')));
CREATE INDEX reseller_leads_owner_created ON public.reseller_leads(reseller_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.pay_referral_commission(_sale uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Somente o Super Admin pode confirmar o repasse'; END IF; UPDATE public.referral_sales SET status='pago',paid_at=coalesce(paid_at,now()) WHERE id=_sale AND status='pendente_a_pagar'; IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.referral_sales WHERE id=_sale AND status='pago') THEN RAISE EXCEPTION 'Venda não disponível para pagamento'; END IF; END $$;
REVOKE ALL ON FUNCTION public.pay_referral_commission(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.pay_referral_commission(uuid) TO authenticated;
REVOKE UPDATE ON public.referral_sales FROM authenticated;